from itertools import permutations

people = ['Harper', 'Jordan', 'Quinn', 'Sawyer']
colors = ['blue', 'green', 'white', 'yellow']
pets = ['bird', 'dog', 'fish', 'rabbit']
drinks = ['cocoa', 'coffee', 'tea', 'water']

def solve():
    for people_perm in permutations(range(4)):
        for colors_perm in permutations(range(4)):
            for pets_perm in permutations(range(4)):
                for drinks_perm in permutations(range(4)):
                    # people_perm[i] = person index in house i
                    # colors_perm[i] = color index in house i
                    # pets_perm[i] = pet index in house i
                    # drinks_perm[i] = drink index in house i

                    # Helper functions to find which house contains a specific person/color/pet/drink
                    def person_house(name):
                        return people_perm.index(people.index(name))

                    def color_house(name):
                        return colors_perm.index(colors.index(name))

                    def pet_house(name):
                        return pets_perm.index(pets.index(name))

                    def drink_house(name):
                        return drinks_perm.index(drinks.index(name))

                    # Check all constraints
                    if person_house('Sawyer') != drink_house('water'):
                        continue
                    if person_house('Harper') != pet_house('fish'):
                        continue
                    if drink_house('coffee') != pet_house('fish'):
                        continue
                    if pet_house('fish') + 1 != person_house('Quinn'):
                        continue
                    if abs(pet_house('dog') - drink_house('water')) != 1:
                        continue
                    if pet_house('dog') + 1 != color_house('yellow'):
                        continue
                    if person_house('Quinn') == drink_house('cocoa'):
                        continue
                    if color_house('white') != pet_house('rabbit'):
                        continue
                    if color_house('green') != drink_house('cocoa'):
                        continue
                    if abs(color_house('blue') - person_house('Harper')) != 1:
                        continue

                    # Found valid solution
                    green_person_idx = people_perm[color_house('green')]
                    return people[green_person_idx]

    return None

result = solve()
print(f"ANSWER: {result}")
